equation_logic_text:
// Logic template
var calc_output = [];

var tc = parseFloat(tc);
var hdl = parseFloat(hdl);
var tg = parseFloat(tg);

if (UOMSYSTEM == false) { 
    var tc = tc / 0.02586; 
    var hdl = hdl / 0.02586;
    var tg = tg / 0.0113;
}

var nonhdl = tc - hdl;

// Calculate score
var score = tc / 0.948 - hdl / 0.971 - (tg / 8.56 + (tg * nonhdl) / 2140 - (tg ** 2) / 16100) - 9.44;
var score_mmol = score / 38.67;

var modscore = nonhdl - tg / 8.37 - (tg * nonhdl) / 2640 + (tg ** 2) / 17400;
var modscore_mmol = modscore / 38.67;

// Output
if (UOMSYSTEM == true) {
    if (tc < hdl) {
        calc_output.push({
            name: 'mini',
            value: '',
            value_text: '',
            message: 'TC must be greater than HDL-C. Please review the input values.'
        });
        calc_output.push({
            name: '10669_Sampson Equation for LDL-C_result',
            value: '',
            value_text: '',
            message: 'TC must be greater than HDL-C. Please review the input values.'
        });
    } else if (score < 0 || modscore < 0) {
        calc_output.push({
            name: 'mini',
            value: '',
            value_text: '',
            message: 'The estimated LDL-C is below 0 mg/dL, which is not clinically plausible. Please review the input values.'
        });
        calc_output.push({
            name: '10669_Sampson Equation for LDL-C_result',
            value: '',
            value_text: '',
            message: 'The estimated LDL-C is below 0 mg/dL, which is not clinically plausible. Please review the input values.'
        });
    } else {
        calc_output.push({
            name: 'mini',
            value: score.toFixed(0),
            value_text: 'mg/dL',
            message: 'Sampson Equation for LDL-C <br/>(Modified Sampson LDL-C: ' + modscore.toFixed(0) + 'mg/dL)'
        });
        calc_output.push({
            name: '10669_Sampson Equation for LDL-C_result',
            value: score.toFixed(0),
            value_text: 'mg/dL',
            message: 'Equivalent to ' +  score_mmol.toFixed(2) + ' mmol/L<br/>Non-HDL-C: ' + nonhdl.toFixed(0) + ' mg/dL<br/><br/>Sampson Equation for LDL-C'
        });
        calc_output.push({
            name: '10669_Sampson Equation for LDL-C_result',
            value: modscore.toFixed(0),
            value_text: 'mg/dL',
            message: 'Equivalent to ' +  modscore_mmol.toFixed(2) + ' mmol/L<br/><br/>Modified Sampson Equation for LDL-C'
        });
    }

} else if (UOMSYSTEM == false) {
    if (tc < hdl) {
        calc_output.push({
            name: 'mini',
            value: '',
            value_text: '',
            message: 'TC must be greater than HDL-C. Please review the input values.'
        });
        calc_output.push({
            name: '10669_Sampson Equation for LDL-C_result',
            value: '',
            value_text: '',
            message: 'TC must be greater than HDL-C. Please review the input values.'
        });
    } else if (score < 0) {
        calc_output.push({
            name: 'mini',
            value: '',
            value_text: '',
            message: 'The estimated LDL-C is below 0 mg/dL, which is not clinically plausible. Please review the input values.'
        });
        calc_output.push({
            name: '10669_Sampson Equation for LDL-C_result',
            value: '',
            value_text: '',
            message: 'The estimated LDL-C is below 0 mg/dL, which is not clinically plausible. Please review the input values.'
        });
    } else {
        nonhdl = nonhdl * 0.02586;
        calc_output.push({
            name: 'mini',
            value: score_mmol.toFixed(2),
            value_text: 'mmol/L',
            message: 'Sampson Equation for LDL-C<br/>(Modified Sampson LDL-C: ' + modscore_mmol.toFixed(2) + 'mmol/L)'
        });
        calc_output.push({
            name: '10669_Sampson Equation for LDL-C_result',
            value: score_mmol.toFixed(2),
            value_text: 'mmol/L',
            message: 'Equivalent to ' +  score.toFixed(0) + ' mg/dL<br/>Non-HDL-C: ' + nonhdl.toFixed(2) + ' mmol/L<br/><br/>Sampson Equation for LDL-C'
        });
        calc_output.push({
            name: '10669_Sampson Equation for LDL-C_result',
            value: modscore_mmol.toFixed(2),
            value_text: 'mmol/L',
            message: 'Equivalent to ' +  modscore.toFixed(0) + ' mg/dL<br/><br/>Modified Sampson Equation for LDL-C'
        });
    }
}
